mapper.select:

SELECT COALESCE(SUM(l.quantity * COALESCE(l.unit_cost_cents, 0)), 0)
FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id
WHERE o.created_at >= #{since}


SELECT COALESCE(SUM(l.quantity * COALESCE(l.unit_cost_cents, 0)), 0)
FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id
WHERE o.created_at >= #{start} AND o.created_at < #{end}

SELECT o.device_id AS c0, COALESCE(SUM(l.quantity), 0) AS c1, COALESCE(SUM(l.line_amount_cents), 0) AS c2, COALESCE(SUM(l.quantity * COALESCE(l.unit_cost_cents, 0)), 0) AS c3, COUNT(DISTINCT o.order_id) AS c4, COALESCE(MAX(rf.refunded_cents), 0) AS c5, COALESCE(MAX(rf.refund_order_count), 0) AS c6 FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id LEFT JOIN ( SELECT device_id, SUM(COALESCE(refunded_cents, 0)) AS refunded_cents, COUNT(*) FILTER (WHERE COALESCE(refunded_cents, 0) > 0) AS refund_order_count FROM cabinet_order WHERE created_at >= #{start} AND created_at < #{end}
AND device_id IN #{__item}
GROUP BY device_id ) rf ON rf.device_id = o.device_id WHERE o.created_at >= #{start} AND o.created_at < #{end}
AND o.device_id IN #{__item}
GROUP BY o.device_id ORDER BY SUM(l.line_amount_cents) DESC

SELECT UPPER(COALESCE(NULLIF(TRIM(o.pay_channel), ''), 'UNKNOWN')) AS c0, COALESCE(SUM(l.quantity), 0) AS c1, COALESCE(SUM(l.line_amount_cents), 0) AS c2, COALESCE(SUM(l.quantity * COALESCE(l.unit_cost_cents, 0)), 0) AS c3, COUNT(DISTINCT o.order_id) AS c4, COALESCE(MAX(rf.refunded_cents), 0) AS c5, COALESCE(MAX(rf.refund_order_count), 0) AS c6 FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id LEFT JOIN ( SELECT UPPER(COALESCE(NULLIF(TRIM(pay_channel), ''), 'UNKNOWN')) AS pay_channel, SUM(COALESCE(refunded_cents, 0)) AS refunded_cents, COUNT(*) FILTER (WHERE COALESCE(refunded_cents, 0) > 0) AS refund_order_count FROM cabinet_order WHERE created_at >= #{start} AND created_at < #{end}
AND device_id IN #{__item}
GROUP BY UPPER(COALESCE(NULLIF(TRIM(pay_channel), ''), 'UNKNOWN')) ) rf ON rf.pay_channel = UPPER(COALESCE(NULLIF(TRIM(o.pay_channel), ''), 'UNKNOWN')) WHERE o.created_at >= #{start} AND o.created_at < #{end}
AND o.device_id IN #{__item}
GROUP BY UPPER(COALESCE(NULLIF(TRIM(o.pay_channel), ''), 'UNKNOWN')) ORDER BY SUM(l.line_amount_cents) DESC

