SELECT COALESCE(SUM(l.line_amount_cents), 0)
FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id
WHERE o.device_id IN
#{__item}
AND o.created_at >= #{start} AND o.created_at < #{end}

SELECT to_char(o.created_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD') AS c0, COALESCE(SUM(l.quantity), 0) AS c1, COALESCE(SUM(l.line_amount_cents), 0) AS c2, COALESCE(SUM(l.quantity * COALESCE(l.unit_cost_cents, 0)), 0) AS c3, COUNT(DISTINCT o.order_id) AS c4 FROM cabinet_order_line l JOIN cabinet_order o ON l.order_id = o.order_id WHERE o.created_at >= #{start} AND o.created_at < #{end} AND o.status <> 'FAILED' AND o.merchant_id IN #{__item}
AND o.device_id IN #{__item}
GROUP BY to_char(o.created_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD') ORDER BY c0

SELECT to_char(COALESCE(refunded_at, created_at) AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD') AS c0, COALESCE(SUM(CASE WHEN UPPER(COALESCE(NULLIF(TRIM(pay_channel), ''), 'UNKNOWN')) <> 'BALANCE' THEN COALESCE(refunded_cents, 0) ELSE 0 END), 0) AS c1, COALESCE(SUM(CASE WHEN UPPER(COALESCE(NULLIF(TRIM(pay_channel), ''), 'UNKNOWN')) = 'BALANCE' THEN COALESCE(refunded_cents, 0) ELSE 0 END), 0) AS c2, COUNT(*) FILTER (WHERE COALESCE(refunded_cents, 0) > 0) AS c3 FROM cabinet_order WHERE COALESCE(refunded_at, created_at) >= #{start} AND COALESCE(refunded_at, created_at) < #{end} AND COALESCE(refunded_cents, 0) > 0 AND status <> 'FAILED' AND merchant_id IN #{__item}
AND device_id IN #{__item}
GROUP BY to_char(COALESCE(refunded_at, created_at) AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD') ORDER BY c0
